scwin.fn_GetParentValue = function() {
    //gAcptNo = frame.Provider("../").gAcptNo;
    //gMainFormCd = frame.Provider("../").gMainFormCd;
    //gFormVer = frame.Provider("../").gFormVer;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    //alert("회사코드:"+gIsurCd);

};



// 화면 로딩시 디폴트 검색
scwin.fn_Search = function() {
    var url = "/DisclosureSearch.do?method=listAllDsclAcptIsur&inputMessageId=ALLDSCLISUR_IN" + "&outputMessageId=ALLDSCLISUR_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&TYPE=TD" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclAcptListAll.DataID = encodeURI(url);
    dts_DsclAcptListAll.reset();
    $c.cm.ShowWin(grd_DsclAcptListAll);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclAcptListAll.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclAcptListAll.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclAcptListAll.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclAcptListAll.getCellData(eval(obj), "ISUR_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.grd_DsclAcptListAll_OnClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "ACPT_DATE") {
        // 부모창에 셋팅하기
        $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
        $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_DATE"));
        $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
        //self.close();
        await $c.frame.CloseFrame();
    }
};
scwin.grd_DsclAcptListAll_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    var result = "";
    if (colid == "DOC_TITLE") {
        /*
        var url = "/dsclproc/ULDSTF10001.gfm";
        var winTitle ="임시제목  - (회사명/보고서명/접수날짜)";
        frame.CreateDialogFrame("gform", url , winTitle ,100, 10, 1000, 800, "window" );
        //frame.CreateFrame("viewer", url , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);
        */
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, 'R');
    } else if (colid == "ACPT_DATE") {
        // 부모창에 셋팅하기
        $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
        $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_DATE"));
        $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
        //self.close();
        await $c.frame.CloseFrame();
    }
};
scwin.dts_DsclAcptListAll_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclAcptListAll);
};
scwin.dts_DsclAcptListAll_OnLoadCompleted = function(rowcount) {
    if (dts_DsclAcptListAll.errorMsg) {
        $c.win.alert(dts_DsclAcptListAll.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin();
};
scwin.btn_Close_onclick = async function() {
    //self.close();
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_DsclAcptListAll, "제출보고서 목록", "", "2");
};
scwin.gform_onload = function() {
    scwin.fn_GetParentValue();
    //fn_getParam();

    // 가우스헤더 셋팅
    //dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
    //dts_StudyCond.reset();	

    scwin.fn_Search();
};
